--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be UPROPERTY: without a GC reference the tracker is collected
	// after BeginPlay and OnGoalScored then calls AddPoints on a stale object.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker was a raw UObject pointer with no UPROPERTY marker, so garbage collection (log: 'Collecting garbage: 412 objects purged' ~1 min before the crash) reclaimed the object created in BeginPlay. OnGoalScored then called UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) through the stale pointer, causing EXCEPTION_ACCESS_VIOLATION. Fixed by making it a UPROPERTY TObjectPtr in ArenaGameMode.h. The editor hid this because GC there is less aggressive and the object stayed referenced.",
  "no_colors_cause": "The palette DA_Primary is loaded by string path with LoadObject (/Game/Data/Palettes/DA_Primary.DA_Primary), which the cook never sees as a hard reference, and with bCookAll=False the /Game/Data/Palettes directory was not in DirectoriesToAlwaysCook (only Effects was). So the asset was missing from the pak and the shipping log shows 'Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'Palette is null, using fallback gray', leaving the arena gray. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
